B.a_x=s(["missing"],t.s)
B.eBL=new A.dh("q7",B.cj,"","You pierce my soul. I am half agony, half hope.","Jane Austen, Persuasion (1817)",B.a_x)
B.a_r=s(["kind"],t.s)
B.eBa=new A.dh("q8",B.cj,"","There is no charm equal to tenderness of heart.","Jane Austen, Emma (1815)",B.a_r)
B.rA=s(["close"],t.s)
B.eC_=new A.dh("q9",B.cj,"","Whatever our souls are made of, his and mine are the same.","Emily Bront\xeb, Wuthering Heights (1847)",B.rA)
B.eBi=new A.dh("q10",B.cj,"","You are part of my existence, part of myself.","Charles Dickens, Great Expectations (1861)",B.rA)
B.eBd=new A.dh("q11",B.cj,"","What greater thing is there for two human souls, than to feel that they are joined for life\u2014to strengthen each other in all labour, to rest on each other in all sorrow, to minister to each other in all pain\u2026","George Eliot, Adam Bede (1859)",B.yV)
B.yU=s(["space"],t.s)
B.eBQ=new A.dh("q12",B.cj,"","Love one another, but make not a bond of love:\nLet it rather be a moving sea between the shores of your souls.","Kahlil Gibran, The Prophet (1923)",B.yU)
B.eBE=new A.dh("q13",B.cj,"","And stand together yet not too near together:\nFor the pillars of the temple stand apart,\nAnd the oak tree and the cypress grow not in each other\u2019s shadow.","Kahlil Gibran, The Prophet (1923)",B.yU)
B.eB7=new A.dh("q14",B.cj,"","Love gives naught but itself and takes naught but from itself.\nLove possesses not nor would it be possessed;\nFor love is sufficient unto love.","Kahlil Gibran, The Prophet (1923)",B.D6)
B.eBt=new A.dh("q15",B.cj,"","Many waters cannot quench love, neither can the floods drown it.","Song of Solomon 8:7, King James Bible (1611)",B.yV)
B.eBb=new A.dh("q16",B.cj,"","Set me as a seal upon thine heart.","Song of Solomon 8:6, King James Bible (1611)",B.rA)
B.eBq=new A.dh("q17",B.cj,"","O my Luve is like a red, red rose\nThat\u2019s newly sprung in June.","Robert Burns, A Red, Red Rose (1794)",B.CY)
